def main():
    s = SRC.read_text(encoding='utf-8')
    for ru, kz in PAIRS:
        c = s.count(ru)
        if c != 1:
            sys.exit(f'Үзінді {c} рет табылды (күтілгені 1): {ru[:100]}')
        s = s.replace(ru, kz)
    DST.write_text(s, encoding='utf-8')
    print(DST.name, 'дайын')


if __name__ == '__main__':
    main()
